                 val docxParas = doc.select("*")
                     .filter { it.tagName().substringAfter(':').equals("p", ignoreCase = true) }
                 val text = docxParas.joinToString("\n\n") { p ->
                     p.select("*")
                         .filter { it.tagName().substringAfter(':').equals("t", ignoreCase = true) }
