     /**
      * Записи буфера, относящиеся к ЭТОЙ странице.
      *
      * Страница известна по [ocrPageIdentity] — тому же хуку, по которому
      * работает оверлей активной реплики, поэтому в пагере и в вебтуне (где
      * страниц в ленте много одновременно) пометки ложатся именно на ту
      * страницу, к которой относятся. Кэш по [OcrScreenshotBuffer.version]:
      * перерисовка идёт на каждом кадре анимации, фильтровать буфер заново
      * там незачем.
      */
     private fun currentOcrPageMarks(): List<OcrScreenshotEntry>? {
         val identity = ocrPageIdentity ?: return null
         val version = OcrScreenshotBuffer.version
         val cache = ocrPageMarksCache
         if (cache != null && cache.identity == identity && cache.version == version) {
             return cache.entries
         }
         val entries = OcrScreenshotBuffer.forPage(identity.chapterId, identity.pageIndex)
             .filter { it.hasSourceGeometry }
         ocrPageMarksCache = OcrPageMarksCache(identity, version, entries)
         return entries
     }

     private fun drawActiveOcrOverlay(canvas: Canvas) {
         // Выключатель из Настройки → Распознавание: пользователь убирает
         // оверлей совсем, когда текст поверх страницы мешает читать картинку.
         if (!ocrPrefs.ocrPageTextOverlay().get()) return
         val overlayLayout = getOrBuildActiveOverlayLayout() ?: return
         // Подложка под текстом обязательна. Раньше её убрали («solid white
         // background box»), и на светлой странице белый текст поверх белой
         // бумаги просто исчезал — оверлей был, а прочитать его нельзя.
         // Заливка идёт по textRect (области текста), а не по всему
         // boundingBox, и полупрозрачная: картинка под ней остаётся видна.
         val pad = resources.displayMetrics.density * 4f
         val bg = RectF(overlayLayout.textRect).apply { inset(-pad, -pad) }
         val radius = resources.displayMetrics.density * 6f
         canvas.drawRoundRect(bg, radius, radius, ocrOverlayBackgroundPaint)
         canvas.drawRoundRect(bg, radius, radius, ocrOverlayStrokePaint)
         ocrOverlayRenderer.drawOverlay(canvas, overlayLayout)
     }

     private fun resolveInitialSelectionOffset(
         region: mihon.domain.ocr.model.OcrRegion,
         normalizedDisplayText: String,
         localX: Float,
         localY: Float,
     ): Int {
         val overlayLayout = ocrOverlayRenderer.buildLayout(
             bubbleRect = boundingBoxToLocalRect(region.boundingBox) ?: return 0,
             displayText = normalizedDisplayText,
             textOrientation = region.textOrientation,
             highlightRange = null,
         ) ?: return 0
         return if (ocrOverlayRenderer.isPointNearText(overlayLayout, localX, localY)) {
             ocrOverlayRenderer.resolveQueryOffset(overlayLayout, localX, localY)
         } else {
             0
         }
     }

     private fun getOrBuildActiveOverlayLayout(): ReaderOcrOverlayLayout? {
         activeOverlayLayout?.let { return it }

         val overlay = activeOcrOverlay ?: return null
         // Результат OCR страницы нужен как проверка, что оверлей вообще к чему
         // привязан: без распознанной страницы показывать нечего.
         cachedOcrResult ?: return null
         val bubbleRect = boundingBoxToLocalRect(overlay.boundingBox) ?: return null
         return ocrOverlayRenderer.buildLayout(
             bubbleRect = bubbleRect,
             displayText = overlay.displayText,
             textOrientation = overlay.textOrientation,
             highlightRange = overlay.highlightRange,
         )?.also {
             activeOverlayLayout = it
         }
     }

     private fun boundingBoxToLocalRect(
         boundingBox: OcrBoundingBox,
     ): RectF? {
         val localRect = boundingBoxToDisplayedRect(boundingBox) ?: return null
         return RectF(
             localRect.left.coerceIn(0f, width.toFloat()),
             localRect.top.coerceIn(0f, height.toFloat()),
             localRect.right.coerceIn(0f, width.toFloat()),
             localRect.bottom.coerceIn(0f, height.toFloat()),
         ).takeIf { it.width() > 0f && it.height() > 0f }
     }

     private fun invalidateActiveOverlayLayout() {
         activeOverlayLayout = null
     }

     private fun rawPointToLocalPoint(rawX: Float, rawY: Float): PointF? {
         val location = IntArray(2)
         getLocationOnScreen(location)
         return PointF(rawX - location[0], rawY - location[1])
     }

     private fun screenRectToLocalRect(screenRect: RectF): RectF? {
         val topLeftLocal = rawPointToLocalPoint(screenRect.left, screenRect.top) ?: return null
         val bottomRightLocal = rawPointToLocalPoint(screenRect.right, screenRect.bottom) ?: return null
         return RectF(
             min(topLeftLocal.x, bottomRightLocal.x),
             min(topLeftLocal.y, bottomRightLocal.y),
             max(topLeftLocal.x, bottomRightLocal.x),
             max(topLeftLocal.y, bottomRightLocal.y),
         )
     }

     /**
      * Прямоугольник реально отображаемой картинки внутри вьюхи, в пикселях.
      *
      * Нужен подсветке реплик: страница почти никогда не занимает всю область
      * (поля сверху/снизу у манги, по бокам у вебтуна), поэтому нормализованные
      * координаты OCR нельзя умножать на размер контейнера — рамки уезжают.
      */
     fun displayedImageRectOrNull(): RectF? = displayedImageLocalRect()

     /**
      * Размер ИСХОДНОГО изображения страницы (того же, в координатах которого
      * работает [sourceRectForScreenRect]) — в пикселях файла.
      *
      * Нужен записи скриншота: без него нормализованные координаты распознанных
      * регионов нечем перевести в пиксели страницы, и вернуть пометки на книгу
      * невозможно. null — картинка ещё не готова.
      */
     fun sourceSizeOrNull(): Pair<Int, Int>? {
         return when (val currentPageView = pageView) {
             is SubsamplingScaleImageView ->
                 if (currentPageView.isReady && currentPageView.sWidth > 0 && currentPageView.sHeight > 0) {
                     currentPageView.sWidth to currentPageView.sHeight
                 } else {
                     null
                 }
             is ImageView -> currentPageView.drawable?.let {
                 it.intrinsicWidth to it.intrinsicHeight
             }?.takeIf { (it.first > 0 && it.second > 0) }
             else -> null
         }
     }

     private fun displayedImageLocalRect(): RectF? {
         return when (val currentPageView = pageView) {
             is SubsamplingScaleImageView -> {
                 if (!currentPageView.isReady) return null
                 val topLeft = currentPageView.sourceToViewCoord(0f, 0f) ?: return null
                 val bottomRight = currentPageView.sourceToViewCoord(
                     currentPageView.sWidth.toFloat(),
                     currentPageView.sHeight.toFloat(),
                 ) ?: return null
                 RectF(
                     min(topLeft.x, bottomRight.x),
                     min(topLeft.y, bottomRight.y),
                     max(topLeft.x, bottomRight.x),
                     max(topLeft.y, bottomRight.y),
                 )
             }
             is ImageView -> {
                 val drawable = currentPageView.drawable ?: return null
                 RectF(0f, 0f, drawable.intrinsicWidth.toFloat(), drawable.intrinsicHeight.toFloat()).also(
                     currentPageView.imageMatrix::mapRect,
                 )
             }
             else -> null
         }
     }

     private fun localPointToSourcePoint(localX: Float, localY: Float): PointF? {
         return when (val currentPageView = pageView) {
             is SubsamplingScaleImageView -> {
                 if (!currentPageView.isReady) return null
                 currentPageView.viewToSourceCoord(localX, localY)
             }
             is ImageView -> {
                 val drawable = currentPageView.drawable ?: return null
                 val inverse = Matrix()
                 if (!currentPageView.imageMatrix.invert(inverse)) return null

                 val points = floatArrayOf(localX, localY)
                 inverse.mapPoints(points)
                 val sourceX = points[0]
                 val sourceY = points[1]
                 if (sourceX < 0f || sourceY < 0f ||
                     sourceX > drawable.intrinsicWidth.toFloat() ||
                     sourceY > drawable.intrinsicHeight.toFloat()
                 ) {
                     null
                 } else {
                     PointF(sourceX, sourceY)
                 }
             }
             else -> null
         }
     }

     private fun localPointToFilePoint(localX: Float, localY: Float): PointF? {
         return when (val currentPageView = pageView) {
             is SubsamplingScaleImageView -> currentPageView.viewToFilePoint(localX, localY, fileCropRect)
             else -> localPointToSourcePoint(localX, localY)
         }
     }

     private fun boundingBoxToScreenRect(
         boundingBox: OcrBoundingBox,
     ): RectF? {
         val localRect = boundingBoxToDisplayedRect(boundingBox) ?: return null
         val location = IntArray(2)
         getLocationOnScreen(location)
         return RectF(localRect).apply { offset(location[0].toFloat(), location[1].toFloat()) }
     }

     private fun boundingBoxToDisplayedRect(
         boundingBox: OcrBoundingBox,
     ): RectF? {
         return when (val currentPageView = pageView) {
             is SubsamplingScaleImageView -> {
                 // Координаты региона нормализованы, поэтому переносим их сразу
                 // в пиксели ИСХОДНОГО изображения страницы, а не в пиксели
                 // битмапа, который видел OCR: он уменьшен и обрезан по видимой
                 // области, и от его размера зависел бы весь результат. Обрезка
                 // рамок (crop-borders) сдвигает картинку внутри файла — этот
                 // сдвиг добавляем здесь, дальше fileToViewRect развернёт его
                 // обратно вместе с поворотом и зумом.
                 val cropLeft = fileCropRect?.left ?: 0
                 val cropTop = fileCropRect?.top ?: 0
                 val sourceRect = RectF(
                     boundingBox.left * currentPageView.sWidth + cropLeft,
                     boundingBox.top * currentPageView.sHeight + cropTop,
                     boundingBox.right * currentPageView.sWidth + cropLeft,
                     boundingBox.bottom * currentPageView.sHeight + cropTop,
                 )
                 currentPageView.fileToViewRect(sourceRect, fileCropRect)
             }
             is ImageView -> {
                 val drawable = currentPageView.drawable ?: return null
                 val sourceRect = boundingBox.toSourceRect(
                     imageWidth = drawable.intrinsicWidth,
                     imageHeight = drawable.intrinsicHeight,
                 )
                 RectF(sourceRect).also(currentPageView.imageMatrix::mapRect)
             }
             else -> null
         }
     }

     private fun Int.getSystemScaledDuration(): Int {
         return (this * context.animatorDurationScale).toInt().coerceAtLeast(1)
     }

     /**
      * All of the config except [zoomDuration] will only be used for non-animated image.
      */
     data class Config(
         val zoomDuration: Int,
         val minimumScaleType: Int = SCALE_TYPE_CENTER_INSIDE,
         val cropBorders: Boolean = false,
         val zoomStartPosition: ZoomStartPosition = ZoomStartPosition.CENTER,
         val landscapeZoom: Boolean = false,
     )

     enum class ZoomStartPosition {
         LEFT,
         CENTER,
         RIGHT,
     }
 }

