                     var head = 0, foot = vh;
                     var chrome = document.querySelectorAll('header, footer, nav, [class*="header"], [class*="footer"], [class*="toolbar"], [class*="reader-top"], [class*="reader-bottom"]');
                     for (var k = 0; k < chrome.length; k++) {
