         while (current != null) {
             if (
                 current is UnknownHostException ||
                 current is ConnectException ||
                 current is SocketTimeoutException ||
                 current.message?.contains("Unable to resolve host", ignoreCase = true) == true
             ) {
                 return true
             }
             current = current.cause
         }
         return false
     }

